def solve_shift_pay(text):
    data = text.split()
    n = int(data[0])
    NEG = float('-inf')
    rest, one, two = 0, NEG, NEG   # best ending on rest, one worked, two worked
    for x in map(int, data[1:1 + n]):
        rest, one, two = max(rest, one, two), rest + x, one + x
    return str(max(rest, one, two))
